#pragma once
class BloodQueenRuntime final:public FestergutRuntime,public ICC::BloodQueenPort {
 ICC::BloodQueen queen;uint32_t mirror=0,fearEnd=0,nextWorld=0,nextShroud=0;float flightHeight=0;bool ruined=false;
 struct Vampire {uint32_t end=0;unsigned stage=0;};std::map<uint32_t,Vampire> vampires;
 std::map<uint32_t,uint32_t> shadows;std::vector<uint32_t> pact;uint32_t pactEnd=0,pactStarted=0;
 struct Pool {Vec point;uint32_t end=0,activeAt=0;};std::vector<Pool> pools;std::set<uint32_t> airTargets;
 uint32_t QueenTank(){uint32_t pid=0;double best=-1;for(auto p:Living(run)){auto id=P::GetPlayerID(p);if(vampires[id].stage==3)continue;double score=double(threat[id])+1/(1+Distance(Position(p),Position(boss)));if(score>best){best=score;pid=id;}}return pid;}
 std::vector<entt::entity> Candidates(bool excludeTank=true){auto list=Living(run);auto tank=QueenTank();list.erase(std::remove_if(list.begin(),list.end(),[&](auto p){auto pid=P::GetPlayerID(p);return vampires[pid].stage==3||(excludeTank&&(pid==tank||pid==mirror));}),list.end());if(list.empty()&&excludeTank)return Candidates(false);for(size_t i=list.size();i>1;i--)std::swap(list[i-1],list[random.Uniform(0,uint32_t(i-1))]);return list;}
 void RootState(uint32_t pid){bool root=(fearEnd&&!Due(now,fearEnd))||vampires[pid].stage==3;auto p=Resolve(pid);if(root){run.rooted.insert(pid);if(Alive(run,p))M::Stop(p);}else run.rooted.erase(pid);if(Present(run,p))ecs::ChatSystem::Send(p,CHAT_TYPE_COMMAND,"er_root %d",root?1:0);}
 void GiveEssence(uint32_t pid){auto p=Resolve(pid);if(!Alive(run,p))return;vampires[pid]={now+75000,1};Fx(70877,4,p,Position(p),0);Fx(70879,3,p,Position(p),75000);if(auto m=Participant(run,pid)){m->aura=Mechanic::Strike;m->auraEnd=0;}}
 void RemovePact(){for(auto pid:pact){auto p=Resolve(pid);if(Present(run,p))Fx(71340,4,p,Position(p),0);}pact.clear();pactEnd=0;}
 void HealSelf(entt::entity p,int64_t amount){if(Alive(run,p)&&amount>0)P::SetHP(p,std::min<int64_t>(Points::GetMaxHP(p),P::GetHP(p)+amount));}
 void QueenPeriodic(const ICC::AuraEvent& e){auto pid=e.aura.spec.key.target;auto p=Resolve(pid);if(e.aura.spec.key.spell==71623){if(e.removed){if(Present(run,p))Fx(71623,4,p,Position(p),0);}else if(e.effect==1)Damage(p,Value(71623,1));}else Periodic(e);}
public:
 explicit BloodQueenRuntime(Run& r):FestergutRuntime(r,false),queen(r.id^0x901){queen.Reset(*this);Fx(70986,3,boss,Position(boss),600000);Notice(run,"ER_QUEEN_BEGIN");}
 ~BloodQueenRuntime()override{RemovePact();for(auto& member:run.members){run.rooted.erase(member.pid);auto p=Player(member);if(Present(run,p))ecs::ChatSystem::Send(p,CHAT_TYPE_COMMAND,"er_root 0");}if(Valid(boss))Broadcast(run,"er_lift "+std::to_string(P::GetPacketVID(boss))+" 0");}
 ICC::Difficulty Mode()const override{return run.mode;}
 void Ability(uint32_t id)override{
  if(id==26662){berserk=true;Fx(id,3,boss,Position(boss),600000);Notice(run,"ER_ENRAGE");return;}
  if(id==70838){auto tank=Resolve(QueenTank());if(!Alive(run,tank))return;auto list=Candidates(false);list.erase(std::remove_if(list.begin(),list.end(),[&](auto p){return p==tank;}),list.end());if(list.empty()){mirror=0;return;}auto closest=*std::min_element(list.begin(),list.end(),[&](auto a,auto b){return Distance(Position(a),Position(tank))<Distance(Position(b),Position(tank));});auto pid=P::GetPlayerID(closest);if(pid!=mirror){auto old=Resolve(mirror);if(Present(run,old))Fx(71510,4,old,Position(old),0);mirror=pid;Fx(71510,3,closest,Position(closest),600000);Fx(71510,3,tank,Position(tank),600000);}return;}
  auto list=Candidates();if(list.empty())return;
  M::SendMovePacket(boss,FUNC_MOB_SKILL,0,P::GetX(boss),P::GetY(boss),0);
  if(id==71726){list.erase(std::remove_if(list.begin(),list.end(),[&](auto p){return vampires[P::GetPlayerID(p)].stage!=0;}),list.end());if(list.empty())return;auto p=*std::max_element(list.begin(),list.end(),[&](auto a,auto b){return threat[P::GetPlayerID(a)]<threat[P::GetPlayerID(b)];});GiveEssence(P::GetPlayerID(p));Fx(id,2,p,Position(p));Damage(p,Value(id));Notice(run,"ER_QUEEN_BITE");return;}
  if(id==71623){auto p=Resolve(mirror);if(!Alive(run,p))p=Resolve(QueenTank());if(Alive(run,p))Apply(id,P::GetPlayerID(p),1);return;}
  if(id==71340){RemovePact();auto count=std::min<size_t>(ICC::Raid25(run.mode)?3:2,list.size());if(count<2)return;pactStarted=now;pactEnd=now+28000;for(size_t i=0;i<count;i++){auto p=list[i];pact.push_back(P::GetPlayerID(p));Fx(id,3,p,Position(p),28000);}Notice(run,"ER_QUEEN_PACT");return;}
  if(id==71264){auto p=list.front();shadows[P::GetPlayerID(p)]=now+12000;Fx(id,3,p,Position(p),12000);Notice(run,"ER_QUEEN_SHADOWS");return;}
  if(id==71818){auto count=std::min<size_t>(ICC::Raid25(run.mode)?4:2,list.size());for(size_t i=0;i<count;i++){auto p=list[i];Fx(id,1,p,Position(p),750);Damage(p,Value(id));Fx(id,2,p,Position(p));}return;}
  if(id==71446){auto all=Candidates(false);unsigned count=std::max(1u,unsigned((all.size()+1)/2));for(auto p:all){auto pid=P::GetPlayerID(p);if(airTargets.count(pid))continue;airTargets.insert(pid);Fx(id,1,p,Position(p),750);auto at=Position(p);for(auto other:Living(run))if(Distance(Position(other),at)<=6)Damage(other,Value(id));if(!--count)break;}}
 }
 void Flight(unsigned stage)override{if(stage==0){M::Stop(boss);fearEnd=now+2500;airTargets.clear();for(auto& m:run.members){RootState(m.pid);auto p=Player(m);if(Alive(run,p))Fx(73070,3,p,Position(p),2500);}Notice(run,"ER_QUEEN_AIR");}else if(stage==1){flightHeight=12;Fx(71772,3,boss,Position(boss),7000);}else{flightHeight=0;Fx(71772,4,boss,Position(boss),0);}Broadcast(run,"er_lift "+std::to_string(P::GetPacketVID(boss))+" "+std::to_string(int(flightHeight*100)));}
 bool Action(entt::entity p,const std::string& action,uint32_t target)override{if(action!="bite")return false;auto pid=P::GetPlayerID(p);auto state=vampires.find(pid);auto other=Resolve(target);if(state==vampires.end()||state->second.stage!=2||Due(now,state->second.end)||target==pid||!Alive(run,other)||!Participant(run,target)||vampires[target].stage!=0||Distance(Position(p),Position(other))>5){Notice(p,"ER_QUEEN_BITE_UNAVAILABLE");return true;}GiveEssence(pid);GiveEssence(target);Fx(71726,2,other,Position(other),1500,0,p);Notice(run,"ER_QUEEN_BITE_PASSED");return true;}
 int64_t Outgoing(entt::entity p,int64_t amount)override{auto pid=P::GetPlayerID(p);if(vampires[pid].stage==3)return 0;if(vampires[pid].stage==1){auto bonus=amount;amount+=bonus;HealSelf(p,amount/10);}return amount;}
 void Died(entt::entity actor)override{if(P::IsPC(actor)){auto pid=P::GetPlayerID(actor);vampires.erase(pid);shadows.erase(pid);run.rooted.erase(pid);auras.RemoveTarget(pid,ICC::AuraRemoval::Death);}}
 void Status(entt::entity p)override{FestergutRuntime::Status(p);auto pid=P::GetPlayerID(p);auto v=vampires[pid];ecs::ChatSystem::Send(p,CHAT_TYPE_COMMAND,"er_queen %u %u %u %u %u",run.id,v.stage,v.end&&!Due(now,v.end)?(v.end-now+999)/1000:0,mirror,P::GetPacketVID(boss));ecs::ChatSystem::Send(p,CHAT_TYPE_COMMAND,"er_lift %u %u",P::GetPacketVID(boss),unsigned(flightHeight*100));}
 bool Update(uint32_t time)override{now=time;auto elapsed=now-last;last=now;if(!Valid(boss)||CombatSystem::IsDead(boss))return true;queen.Tick(*this,elapsed);auras.Advance(elapsed,[](auto&){},0);auras.Advance(0,[&](auto& e){QueenPeriodic(e);});
  for(auto& member:run.members){auto p=Player(member);auto pid=member.pid;if(!Alive(run,p))continue;auto& v=vampires[pid];if(v.stage==1&&Due(now,v.end)){v.stage=2;v.end=now+15000;Fx(70879,4,p,Position(p),0);Fx(70877,3,p,Position(p),15000);Aura(run,p,Mechanic::Bite,15000);Notice(p,"ER_QUEEN_THIRST");}else if(v.stage==2&&Due(now,v.end)){v.stage=3;v.end=0;Fx(70877,4,p,Position(p),0);Fx(70923,3,p,Position(p),600000);Notice(run,"ER_QUEEN_CONTROL");}RootState(pid);}
  if(Due(now,nextWorld)){nextWorld=now+1000;unsigned free=0;for(auto p:Living(run)){auto pid=P::GetPlayerID(p);if(vampires[pid].stage!=3){free++;continue;}auto list=Candidates(false);if(!list.empty())Damage(list.front(),int64_t(Points::GetMaxHP(list.front()))/30);}if(!free)ruined=true;
   for(auto it=shadows.begin();it!=shadows.end();){auto p=Resolve(it->first);if(!Alive(run,p)||Due(now,it->second)){it=shadows.erase(it);continue;}if(pools.size()<48){pools.push_back({Position(p),now+20000,now+1250});Fx(71267,5,entt::null,Position(p),20000,3);Emit(Position(p),1250,18750,int(Mechanic::Flame),3);}++it;}
   pools.erase(std::remove_if(pools.begin(),pools.end(),[&](const auto& pool){return Due(now,pool.end);}),pools.end());
   // Overlapping patches apply one periodic aura, not one hit per patch. Give
   // the carrier time to leave each newly deposited patch before it damages.
   for(auto p:Living(run))if(std::any_of(pools.begin(),pools.end(),[&](const auto& pool){return Due(now,pool.activeAt)&&Distance(Position(p),pool.point)<=3;}))Damage(p,Value(71267));
   if(!pact.empty()){bool together=true;for(auto a:pact)for(auto b:pact)if(!Alive(run,Resolve(a))||!Alive(run,Resolve(b))||Distance(Position(Resolve(a)),Position(Resolve(b)))>5)together=false;if(together){RemovePact();Notice(run,"ER_QUEEN_PACT_BROKEN");}else if(Due(now,pactEnd))RemovePact();else for(auto pid:std::vector<uint32_t>(pact)){auto p=Resolve(pid);if(Alive(run,p))for(auto other:Living(run))if(Distance(Position(other),Position(p))<=10)Damage(other,Value(71341)*(100+int((now-pactStarted)/1000)*10)/100);}}
  }
  if(Due(now,nextShroud)){nextShroud=now+2000;auto s=Spell(70986);auto trigger=s?uint32_t(std::max(0,s->effects[0].trigger)):70985u;auto damage=Value(trigger);unsigned count=0;for(auto v:vampires)if(v.second.stage)count++;for(auto p:Living(run))Damage(p,damage*(ICC::Heroic(run.mode)?100+5*count:100)/100);}
  if(!queen.Flying()&&Due(now,nextMelee)){auto p=Resolve(QueenTank());if(Alive(run,p)){nextMelee=now+2000;if(Distance(Position(p),Position(boss))>5.5f)M::Goto(boss,P::GetX(p),P::GetY(p));else{M::Stop(boss);M::SetRotationToXY(boss,P::GetX(p),P::GetY(p));M::SendMovePacket(boss,FUNC_ATTACK,0,P::GetX(boss),P::GetY(boss),0);auto damage=CalcMeleeDamage(boss,p)*(berserk?6:1);Damage(p,damage);auto other=Resolve(mirror);if(other!=p&&Alive(run,other))Damage(other,damage);}}}return !ruined;
 }
};
